import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

// Configuración mejorada de IndexedDB
const DB_NAME = 'FinancialDB';
const STORE_NAME = 'financialData';
const DB_VERSION = 1;

const openDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    
    request.onerror = (event) => {
      console.error('Error al abrir la base de datos:', event.target.error);
      reject(event.target.error);
    };
    
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    
    request.onsuccess = (event) => {
      const db = event.target.result;
      
      // Manejar errores de conexión
      db.onerror = (event) => {
        console.error('Error general de base de datos:', event.target.error);
      };
      
      resolve(db);
    };
  });
};

const getFinancialData = async () => {
  try {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(1);
      
      request.onsuccess = () => {
        if (request.result) {
          console.log('Datos recuperados:', request.result.data);
          resolve(request.result.data);
        } else {
          console.log('No se encontraron datos guardados');
          resolve(null);
        }
      };
      
      request.onerror = (event) => {
        console.error('Error al leer datos:', event.target.error);
        reject(event.target.error);
      };
    });
  } catch (error) {
    console.error('Error en getFinancialData:', error);
    return null;
  }
};

const saveFinancialData = async (data) => {
  try {
    console.log('Guardando datos:', data);
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put({ id: 1, data });
      
      request.onsuccess = () => {
        console.log('Datos guardados exitosamente');
        resolve();
      };
      
      request.onerror = (event) => {
        console.error('Error al guardar datos:', event.target.error);
        reject(event.target.error);
      };
    });
  } catch (error) {
    console.error('Error en saveFinancialData:', error);
    throw error;
  }
};

const SummaryCard = ({ 
  totalIncome: propTotalIncome = 0, 
  totalExpenses: propTotalExpenses = 0, 
  balance: propBalance = 0, 
  currentBalance: propCurrentBalance = 0 
}) => {
  const [financialData, setFinancialData] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0,
    isLoading: true,
    error: null
  });

  // Cargar datos al montar el componente
  useEffect(() => {
    let isMounted = true;
    
    const loadData = async () => {
      try {
        const savedData = await getFinancialData();
        
        if (isMounted) {
          if (savedData) {
            setFinancialData({
              ...savedData,
              isLoading: false,
              error: null
            });
          } else {
            const initialData = {
              totalIncome: propTotalIncome,
              totalExpenses: propTotalExpenses,
              balance: propBalance,
              currentBalance: propCurrentBalance
            };
            
            await saveFinancialData(initialData);
            
            setFinancialData({
              ...initialData,
              isLoading: false,
              error: null
            });
          }
        }
      } catch (error) {
        if (isMounted) {
          console.error('Error al cargar datos:', error);
          setFinancialData(prev => ({
            ...prev,
            isLoading: false,
            error: 'Error al cargar datos'
          }));
        }
      }
    };
    
    loadData();
    
    return () => {
      isMounted = false;
    };
  }, []);

  // Sincronizar con props y guardar cuando cambien
  useEffect(() => {
    let isMounted = true;
    
    const updateData = async () => {
      if (financialData.isLoading) return;
      
      try {
        const newData = {
          ...financialData,
          ...(propTotalIncome !== undefined && { totalIncome: propTotalIncome }),
          ...(propTotalExpenses !== undefined && { totalExpenses: propTotalExpenses }),
          ...(propBalance !== undefined && { balance: propBalance }),
          ...(propCurrentBalance !== undefined && { currentBalance: propCurrentBalance })
        };
        
        if (JSON.stringify(newData) !== JSON.stringify(financialData)) {
          await saveFinancialData(newData);
          
          if (isMounted) {
            setFinancialData({
              ...newData,
              isLoading: false,
              error: null
            });
          }
        }
      } catch (error) {
        console.error('Error al actualizar datos:', error);
        if (isMounted) {
          setFinancialData(prev => ({
            ...prev,
            error: 'Error al guardar datos'
          }));
        }
      }
    };
    
    updateData();
    
    return () => {
      isMounted = false;
    };
  }, [propTotalIncome, propTotalExpenses, propBalance, propCurrentBalance]);

  if (financialData.isLoading) {
    return <div className={styles.card}>Cargando datos financieros...</div>;
  }

  if (financialData.error) {
    return <div className={styles.card}>Error: {financialData.error}</div>;
  }

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance.toFixed(2)}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
